fn solve(nums: Vec<i8>) -> Vec<char> {
    // We assume `nums.len() == 3` as per problem statement.
    let mut v = nums;
    v.sort_unstable();

    let a = v[0];
    let b = v[1];
    let c = v[2];

    let yes = 
        a == 1
        || (a == 2 && b == 2)
        || (a == 2 && b == 4 && c == 4)
        || (a == 3 && b == 3 && c == 3);

    if yes {
        vec!['Y', 'E', 'S']
    } else {
        vec!['N', 'O']
    }
}

